using System;
using System.Collections.Generic;
using System.IO;
namespace Downfield {
public static class FranchiseTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Franchise: "+name);}}
 static Franchise New(){return Franchise.Create(new Profile(),new Roster());}
 public static int Run(){string old=Profile.StorageOverride;string folder=Path.Combine(Path.GetTempPath(),"Downfield-franchise-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
  Franchise f=New();Check(f.Teams.Count==12&&f.Games.Count==66,"12 teams and 66 regular fixtures");HashSet<string> pairs=new HashSet<string>();bool unique=true;for(int round=0;round<11;round++){HashSet<int> teams=new HashSet<int>();foreach(Fixture g in f.Games)if(g.Round==round){teams.Add(g.Home);teams.Add(g.Away);string pair=Math.Min(g.Home,g.Away)+"/"+Math.Max(g.Home,g.Away);if(!pairs.Add(pair))unique=false;}Check(teams.Count==12,"all clubs play once in week "+(round+1));}Check(unique&&pairs.Count==66,"each pairing occurs once");Check(f.Squad(0).Count==25&&f.FreeAgents().Count==30,"25 real players per club and 30 free agents");Check(f.FreeAgents()[0].OVR==99&&f.FreeAgents()[29].OVR==70,"70 to 99 market range");
  f.Credits=200;ClubPlayer signing=f.FreeAgents()[0];int credits=f.Credits,payroll=f.Payroll(0);Check(f.Sign(signing.Id)&&f.Credits==credits-signing.SigningCost&&f.Payroll(0)==payroll+signing.Salary&&signing.Slot==-1,"signing deducts budget and occupies cap as reserve");List<int> slots=f.EligibleSlots(signing);if(slots.Count>0){ClubPlayer previous=f.Starter(0,slots[0]);f.StartPlayer(signing.Id,slots[0]);Check(f.Starter(0,slots[0])==signing&&previous.Slot==-1,"starting assignment swaps exactly one player");Check(!f.Release(signing.Id),"cannot release a starting player");f.StartPlayer(previous.Id,slots[0]);}Check(f.Release(signing.Id)&&signing.Team==-1,"release returns reserve to market");f.Credits=0;Check(!f.Sign(signing.Id),"signing respects funds");f.Credits=200;
  ClubPlayer a=f.Starter(0,0),b=f.Starter(1,0);int id=a.Id;Check(f.Trade(a.Id,b.Id)&&a.Team==1&&b.Team==0&&f.Starter(0,0)==b,"trade exchanges ownership and starting slots");f.Round=8;Check(!f.Trade(b.Id,a.Id),"deadline blocks late trades");f.Round=0;Check(f.Hire(0,2)&&f.Club.CoachOff==2,"hire offensive staff");credits=f.Credits;Check(!f.Hire(0,1)&&f.Credits==credits,"staff cannot downgrade or spend twice");Check(f.Train(0)&&!f.Train(0),"training limited to one per week");Check(f.Relocate(12)&&f.Club.City=="AUSTIN","relocate to unoccupied city");Check(!f.Relocate(1),"occupied city unavailable");f.Edit(8,3,1);Check(f.Club.Mascot=="WOLVES"&&f.Club.Primary==3,"brand customizes club identity");Check(f.Save(),"franchise saves atomically");Franchise loaded=Franchise.Load(new Profile(),new Roster());Check(loaded.Club.City=="AUSTIN"&&loaded.Club.CoachOff==2&&loaded.Players.Find(p=>p.Id==id).Team==1,"complete management save roundtrip");
  Fixture first=f.UserGame;f.FinishGame(first.Id,35,7);int roundAfter=f.Round;credits=f.Credits;Check(!f.FinishGame(first.Id,99,0)&&f.Round==roundAfter&&f.Credits==credits,"duplicate results do not award or advance twice");Check(f.Games.FindAll(g=>g.Round==0&&g.Played).Count==6,"other five fixtures resolved");Check(!f.TakeOver(1),"cannot swap franchises after opener");while(f.Round<11){Fixture game=f.UserGame;f.FinishGame(game.Id,42,3);}Check(f.Seeds.Count==6&&f.Seeds[0]==f.UserTeam&&f.Games.FindAll(g=>g.Round==11).Count==2,"six seeds and two wildcards");Check(f.UserGame==null,"top seed receives bye");f.Advance();Check(f.Round==12&&f.UserGame!=null,"bye advances into semifinals");Fixture semi=f.UserGame;f.FinishGame(semi.Id,28,7);Check(f.Round==13&&f.UserGame!=null,"semifinal winner reaches championship");Fixture final=f.UserGame;f.FinishGame(final.Id,35,14);Check(f.Complete&&f.Titles==1,"championship resolves and awards title");Check(f.Games.Count==71,"postseason contains exactly five games");f.NextSeason();Check(f.Season==2&&f.Round==0&&f.Games.Count==66&&f.Seeds.Count==0,"next season rebuilds schedule");
  for(int season=0;season<4;season++){int guard=0;while(!f.Complete&&guard++<20)f.SimNext();Check(f.Complete&&guard<=15,"simulated full season completes "+season);f.NextSeason();foreach(LeagueTeam team in f.Teams){HashSet<int> assignments=new HashSet<int>();foreach(ClubPlayer p in f.Squad(team.Id))if(p.Slot>=0)assignments.Add(p.Slot);Check(assignments.Count==22,"all 22 starting slots survive contracts / club "+team.Id);}}
  f=New();ClubPlayer injured=f.Starter(0,1);injured.InjuryWeeks=2;Simulation sim=new Simulation(17);sim.Practice=true;f.Apply(sim,1);sim.NewGame();Check(sim.Players[1].ClubId!=injured.Id&&sim.Players[1].Role=="RB","reserve replaces injured starter");int weeks=injured.InjuryWeeks;f.SimNext();Check(injured.InjuryWeeks==weeks-1,"injury recovers once per league week");f=New();List<int> hurt=new List<int>();hurt.Add(f.Starter(0,0).Id);first=f.UserGame;f.FinishGame(first.Id,17,10,hurt);Check(f.Players.Find(p=>p.Id==hurt[0]).InjuryWeeks>=1,"new match injury persists beyond current week");
  f=New();f.UserTeam=1;f.Save();f.Credits=321;f.Save();File.WriteAllText(Franchise.SavePath,"broken");loaded=Franchise.Load(new Profile(),new Roster());Check(loaded.UserTeam==1&&loaded.Credits!=321,"corrupt primary recovers prior atomic backup");
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}Console.WriteLine("Franchise: "+checks+" checks, "+failures+" failures");return failures;}
}
}
